struct IslandReference { double longitude, latitude, radiusMetres; };
inline constexpr IslandReference kIslandReferences[] = {
    {123.4733333333,25.7433333333,2184.6},
    {123.6816666667,25.9233333333,775.8},
    {124.5583333333,25.9216666667,290.4},
    {123.5416666667,25.7300000000,618.0},
    {123.5500000000,25.7233333333,688.2},
    {123.5433333333,25.7816666667,115.8},
    {123.5666666667,25.7550000000,102.0},
    {123.5066666667,25.7350000000,80.0},
};
inline bool InRing(const Ring& ring, double x, double y) {
    bool inside = false;
    for (std::size_t i=0, j=ring.count-1; i<ring.count; j=i++) {
        const auto a=kPoints[ring.first+i], b=kPoints[ring.first+j];
        if ((a.y>y)!=(b.y>y) && x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x) inside=!inside;
    }
    return inside;
}
inline std::string_view AreaAt(double longitude, double latitude) {
    if (!std::isfinite(longitude) || !std::isfinite(latitude)) return {};
    for (const auto& island : kIslandReferences) {
        if (std::abs(longitude-island.longitude)>.03 || std::abs(latitude-island.latitude)>.03) continue;
        const double dx=(longitude-island.longitude)*111320*std::cos(island.latitude*.017453292519943295);
        const double dy=(latitude-island.latitude)*111320;
        if (dx*dx+dy*dy <= island.radiusMetres*island.radiusMetres) return "DYA";
    }
    for (const auto& polygon : kPolygons) {
        if (longitude<polygon.west || longitude>polygon.east || latitude<polygon.south || latitude>polygon.north) continue;
        if (!InRing(kRings[polygon.firstRing],longitude,latitude)) continue;
        bool hole=false;
        for (std::size_t i=1; i<polygon.ringCount; ++i)
            if (InRing(kRings[polygon.firstRing+i],longitude,latitude)) { hole=true; break; }
        if (!hole) return polygon.area;
    }
    return {};
}
